package com.brahim.whatscraft.crypto

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test
import java.io.File

/**
 * Conformance tests against the relay's reference implementation.
 *
 * The vectors in `src/test/resources/message-vectors.json` are generated by
 * `server/scripts/test-vectors.ts`, which uses WebCrypto - a completely
 * different crypto stack. If these tests pass, the phone and the relay really
 * do speak the same wire format.
 *
 * The last test writes `build/kotlin-sealed.json`, which
 * `server/scripts/verify-sealed.ts` opens with the reference implementation,
 * proving the other direction too.
 */
class MessageCipherTest {

    private val vectors: Vectors = Json { ignoreUnknownKeys = true }.decodeFromString(
        Vectors.serializer(),
        checkNotNull(javaClass.classLoader?.getResourceAsStream("message-vectors.json")) {
            "message-vectors.json is missing - run: cd server && bun run scripts/test-vectors.ts"
        }.bufferedReader().readText(),
    )

    private val alice get() = vectors.sender
    private val bob get() = vectors.recipients.first { it.name == "bob" }
    private val carol get() = vectors.recipients.first { it.name == "carol" }

    @Test
    fun `derives the same key pairs as the reference implementation`() {
        listOf(alice, bob, carol).forEach { actor ->
            assertEquals(
                "${actor.name}: X25519 public key",
                actor.identityPublic,
                Crypto.b64(actor.identityPair().publicKey),
            )
            assertEquals(
                "${actor.name}: Ed25519 public key",
                actor.signingPublic,
                Crypto.b64(actor.signingPair().publicKey),
            )
        }
    }

    @Test
    fun `opens a message sealed by the reference implementation`() {
        val body = vectors.sealed.body.toCipherBody()

        listOf(bob, carol).forEach { recipient ->
            val envelope = vectors.sealed.envelopes.first { it.deviceId == recipient.deviceId }
            val plaintext = MessageCipher.open(
                identity = recipient.identityPair(),
                myDeviceId = recipient.deviceId,
                conversationId = vectors.conversationId,
                messageId = vectors.messageId,
                senderIdentityPublicB64 = alice.identityPublic,
                senderSigningPublicB64 = alice.signingPublic,
                body = body,
                envelope = MessageCipher.WrappedKey(envelope.wrappedKey.iv, envelope.wrappedKey.ct),
            )
            assertEquals("${recipient.name} reads the message", vectors.plaintext, plaintext)
        }
    }

    @Test
    fun `rejects a tampered reference message`() {
        val envelope = vectors.sealed.envelopes.first { it.deviceId == bob.deviceId }
        val ciphertext = Crypto.unb64(vectors.sealed.body.ct)
        ciphertext[0] = (ciphertext[0].toInt() xor 0x01).toByte()

        expectDecryptionFailure(
            identity = bob.identityPair(),
            deviceId = bob.deviceId,
            conversationId = vectors.conversationId,
            messageId = vectors.messageId,
            body = vectors.sealed.body.toCipherBody().copy(ct = Crypto.b64(ciphertext)),
            envelope = MessageCipher.WrappedKey(envelope.wrappedKey.iv, envelope.wrappedKey.ct),
            because = "a tampered message must not open",
        )
    }

    @Test
    fun `binds the message to its conversation`() {
        val envelope = vectors.sealed.envelopes.first { it.deviceId == bob.deviceId }

        expectDecryptionFailure(
            identity = bob.identityPair(),
            deviceId = bob.deviceId,
            conversationId = "some-other-conversation",
            messageId = vectors.messageId,
            body = vectors.sealed.body.toCipherBody(),
            envelope = MessageCipher.WrappedKey(envelope.wrappedKey.iv, envelope.wrappedKey.ct),
            because = "the conversation id is authenticated and must not be swappable",
        )
    }

    @Test
    fun `refuses to unwrap another device's envelope`() {
        val envelope = vectors.sealed.envelopes.first { it.deviceId == bob.deviceId }

        expectDecryptionFailure(
            identity = carol.identityPair(),
            deviceId = carol.deviceId,
            conversationId = vectors.conversationId,
            messageId = vectors.messageId,
            body = vectors.sealed.body.toCipherBody(),
            envelope = MessageCipher.WrappedKey(envelope.wrappedKey.iv, envelope.wrappedKey.ct),
            because = "Carol must not be able to unwrap Bob's envelope",
        )
    }

    @Test
    fun `seals and reopens a message for several devices`() {
        val identitySeed = Crypto.randomKey()
        val signingSeed = Crypto.randomKey()
        val conversationId = "conv-roundtrip"
        val messageId = "msg-roundtrip"
        val text = "Round trip with an emoji 🚀 and ünïcödé"

        val sealed = MessageCipher.seal(
            identity = Crypto.identityFromSeed(identitySeed),
            signing = Crypto.signingFromSeed(signingSeed),
            conversationId = conversationId,
            messageId = messageId,
            plaintext = text,
            devices = listOf(
                MessageCipher.RecipientDevice(bob.deviceId, bob.identityPublic),
                MessageCipher.RecipientDevice(carol.deviceId, carol.identityPublic),
            ),
        )

        assertEquals(2, sealed.envelopes.size)
        assertEquals(MessageCipher.ALGORITHM, sealed.body.alg)

        listOf(bob, carol).forEach { recipient ->
            val envelope = sealed.envelopes.first { it.deviceId == recipient.deviceId }
            val opened = MessageCipher.open(
                identity = recipient.identityPair(),
                myDeviceId = recipient.deviceId,
                conversationId = conversationId,
                messageId = messageId,
                senderIdentityPublicB64 = Crypto.b64(Crypto.identityFromSeed(identitySeed).publicKey),
                senderSigningPublicB64 = Crypto.b64(Crypto.signingFromSeed(signingSeed).publicKey),
                body = sealed.body,
                envelope = MessageCipher.WrappedKey(envelope.wrappedKey.iv, envelope.wrappedKey.ct),
            )
            assertEquals(recipient.name, text, opened)
        }
    }

    @Test
    fun `safety number matches the reference implementation`() {
        val expected = vectors.safetyNumber

        assertEquals(expected, MessageCipher.safetyNumber(alice.identityPublic, bob.identityPublic))
        // The same number on both phones, whichever way round they compute it.
        assertEquals(expected, MessageCipher.safetyNumber(bob.identityPublic, alice.identityPublic))
        assertEquals(12, expected.split(" ").size)
        assertEquals(60, expected.count(Char::isDigit))
        assertNotEquals(expected, MessageCipher.safetyNumber(alice.identityPublic, carol.identityPublic))
    }

    /**
     * Writes a message sealed on this side so the relay's implementation can
     * open it (`cd server && bun run scripts/verify-sealed.ts`).
     */
    @Test
    fun `publishes a sealed message for the reference implementation`() {
        val identitySeed = Crypto.randomKey()
        val signingSeed = Crypto.randomKey()
        val senderIdentity = Crypto.identityFromSeed(identitySeed)
        val senderSigning = Crypto.signingFromSeed(signingSeed)

        val conversationId = "conv-kotlin-to-bun"
        val messageId = "msg-kotlin-to-bun"
        val text = "Sealed on Android, opened on the relay 🔐"

        val sealed = MessageCipher.seal(
            identity = senderIdentity,
            signing = senderSigning,
            conversationId = conversationId,
            messageId = messageId,
            plaintext = text,
            devices = listOf(
                MessageCipher.RecipientDevice(bob.deviceId, bob.identityPublic),
                MessageCipher.RecipientDevice(carol.deviceId, carol.identityPublic),
            ),
        )

        val payload = KotlinSealed(
            conversationId = conversationId,
            messageId = messageId,
            plaintext = text,
            sender = KotlinActor(
                deviceId = "device-android",
                identityPublic = Crypto.b64(senderIdentity.publicKey),
                signingPublic = Crypto.b64(senderSigning.publicKey),
                identitySeed = Crypto.b64(identitySeed),
                signingSeed = Crypto.b64(signingSeed),
            ),
            recipients = listOf(bob, carol).map { actor ->
                KotlinActor(
                    deviceId = actor.deviceId,
                    identityPublic = actor.identityPublic,
                    signingPublic = actor.signingPublic,
                    identitySeed = actor.identitySeed,
                    signingSeed = actor.signingSeed,
                )
            },
            sealed = SealedOutput(
                body = Body(sealed.body.alg, sealed.body.iv, sealed.body.ct, sealed.body.sig),
                envelopes = sealed.envelopes.map { envelope ->
                    Envelope(
                        deviceId = envelope.deviceId,
                        wrappedKey = WrappedKey(envelope.wrappedKey.iv, envelope.wrappedKey.ct),
                    )
                },
            ),
        )

        val target = File("build/kotlin-sealed.json")
        target.parentFile?.mkdirs()
        target.writeText(Json { prettyPrint = true }.encodeToString(KotlinSealed.serializer(), payload))
        assertTrue("kotlin-sealed.json was not written", target.length() > 0)
    }

    // ------------------------------------------------------------- helpers ---

    private fun expectDecryptionFailure(
        identity: Crypto.IdentityPair,
        deviceId: String,
        conversationId: String,
        messageId: String,
        body: MessageCipher.Body,
        envelope: MessageCipher.WrappedKey,
        because: String,
    ) {
        try {
            MessageCipher.open(
                identity = identity,
                myDeviceId = deviceId,
                conversationId = conversationId,
                messageId = messageId,
                senderIdentityPublicB64 = alice.identityPublic,
                senderSigningPublicB64 = alice.signingPublic,
                body = body,
                envelope = envelope,
            )
            fail(because)
        } catch (expected: MessageCipher.DecryptionFailed) {
            assertTrue(expected.message!!.isNotBlank())
        }
    }

    private fun Actor.identityPair(): Crypto.IdentityPair =
        Crypto.identityFromSeed(Crypto.unb64(identitySeed))

    private fun Actor.signingPair(): Crypto.SigningPair =
        Crypto.signingFromSeed(Crypto.unb64(signingSeed))

    private fun Body.toCipherBody() = MessageCipher.Body(alg, iv, ct, sig)
}

// --------------------------------------------------------------------- json --

@Serializable
private data class Vectors(
    val conversationId: String,
    val messageId: String,
    val plaintext: String,
    val sender: Actor,
    val recipients: List<Actor>,
    val sealed: SealedOutput,
    val safetyNumber: String,
)

@Serializable
private data class Actor(
    val name: String,
    val deviceId: String,
    val identityPublic: String,
    val signingPublic: String,
    /** Raw 32-byte seeds, base64: the last 32 bytes of the PKCS#8 form. */
    val identitySeed: String,
    val signingSeed: String,
)

@Serializable
private data class SealedOutput(val body: Body, val envelopes: List<Envelope>)

@Serializable
private data class Body(val alg: String, val iv: String, val ct: String, val sig: String)

@Serializable
private data class Envelope(val deviceId: String, val wrappedKey: WrappedKey)

@Serializable
private data class WrappedKey(val iv: String, val ct: String)

@Serializable
private data class KotlinSealed(
    val conversationId: String,
    val messageId: String,
    val plaintext: String,
    val sender: KotlinActor,
    val recipients: List<KotlinActor>,
    val sealed: SealedOutput,
)

@Serializable
private data class KotlinActor(
    val deviceId: String,
    val identityPublic: String,
    val signingPublic: String,
    val identitySeed: String,
    val signingSeed: String,
)
